const $notaHeaderForm = $('#formNotaHeader'),
    $notaHeaderModal = $('#modalNotaHeader'),
    notaHeaderFormCek = CirebonwebForm.FormCek($notaHeaderForm);

$(function () {
    $notaHeaderModal.on('shown.bs.modal', function () {
        $('#notaHeaderKonsumen').select2({
            tags: true,
            dropdownParent: $notaHeaderModal
        });
        notaHeaderFormCek.resetInitial();
    }).on('hidden.bs.modal', function () {
        CirebonwebForm.FormReset(this);
        $('#notaHeaderKonsumen.select2-hidden-accessible').select2('destroy');
    });

    $notaHeaderForm.on('change', '#notaHeaderStatusBarang', function () {
        const $tglAmbil = $('#notaHeaderTglAmbil');
        const sudahDiambil = $(this).val() === '1';
        $tglAmbil.prop('disabled', !sudahDiambil);
        if (sudahDiambil && !$tglAmbil.val()) {
            $tglAmbil.val(CirebonwebFormat.Tanggal(new Date(), 'tanggal'));
        } else if (!sudahDiambil) {
            $tglAmbil.val('');
        }
    });

    $notaHeaderForm.validate($.extend(CirebonwebForm.FormValidasi(), {
        rules: {
            tgl_nota: { required: true },
            keterangan: { maxlength: 255 }
        },
        submitHandler: function () {
            if (!notaHeaderFormCek.isChanged()) return false;

            const tglNota = CirebonwebFormat.sqlTanggal($('#notaHeaderTglNota').val());
            const tglAmbilRaw = $('#notaHeaderTglAmbil').val();
            const tglAmbil = tglAmbilRaw ? CirebonwebFormat.sqlTanggal(tglAmbilRaw) : '';
            if (!tglNota || (tglAmbilRaw && !tglAmbil)) {
                $notaHeaderForm.validate().showErrors({
                    tgl_nota: 'Gunakan format tanggal dd-mm-yyyy yang valid.',
                    tgl_ambil: 'Gunakan format tanggal dd-mm-yyyy yang valid.'
                });
                return false;
            }

            const data = $notaHeaderForm.serializeArray().map((item) => {
                if (item.name === 'tgl_nota') item.value = tglNota;
                if (item.name === 'tgl_ambil') item.value = tglAmbil;
                return item;
            });

            CirebonwebForm.FormFetch(`${urlNota}/simpan`, data, 'POST', {
                before_call: function () {
                    if (!notaHeaderFormCek.isChanged()) return false;
                    $('#btnSimpanNotaHeader')
                        .attr('disabled', true)
                        .html('<span class="spinner-border spinner-border-sm mr-1"></span> Loading...');
                },
                after_call: function () {
                    $('#btnSimpanNotaHeader').attr('disabled', false).text('Update');
                }
            }).done(function (response) {
                if (!response.success) return;
                $notaHeaderModal.modal('hide');
                Swal.fire({
                    icon: 'success',
                    title: 'Sukses',
                    html: response.messages,
                    showConfirmButton: false,
                    timer: 1300
                }).then(function () {
                    getDataNota();
                });
            });
            return false;
        }
    }));

    $('.nota-header-date').datepicker({ dateFormat: 'dd-mm-yy' });
});

function editNotaHeader(id) {
    CirebonwebForm.FormFetch(`${urlNota}/getid`, { id }, 'POST', {}).done(function (response) {
        if (!response.success) return;

        const data = response.data;
        $('#notaHeaderId').val(data.id);
        $('#notaHeaderKonsumen').val(data.konsumen_id);
        $('#notaHeaderStatusBarang').val(data.status_barang);
        $('#notaHeaderTglAmbil').prop('disabled', Number(data.status_barang) !== 1);
        $('#notaHeaderKeterangan').val(data.keterangan);
        CirebonwebFormat.isoTanggal('notaHeaderTglNota', data.tgl_nota);
        CirebonwebFormat.isoTanggal('notaHeaderTglAmbil', data.tgl_ambil);
        $notaHeaderModal.modal('show');
    });
}
